// ioBroker object: script.js.common.Smart_BadHzg
// name: Smart_BadHzg
// engineType: Blockly
// enabled: False

var datum, txt, Timer, SmartPlugBad, HzgBadButtonAktiviert, HzgBadPVAktiviert, BerechnungInAktiv;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - smartplug_badhzg.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");
}


// TIMER
schedule("* * * * * *", async () => {
  setState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timeout' /* SmartPlugBad_Timeout */, (Math.min(Math.max(getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timeout').val - 1, 0), 1000)));
  Timer = (typeof Timer === 'number' ? Timer : 0) + 1;
  if (Timer == 60) {
    if (SmartPlugBad) {
      setState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Inaktiv' /* SmartPlugBad_Timer_Inaktiv */, 0, true);
      setState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Aktiv' /* SmartPlugBad_Timer_Aktiv */, (Math.min(Math.max(getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Aktiv').val + 1, 0), 10000)));
    } else {
      setState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Inaktiv' /* SmartPlugBad_Timer_Inaktiv */, (Math.min(Math.max(getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Inaktiv').val + 1, 0), 10000)));
    }
  }
  if (Timer >= 60) {
    Timer = 0;
  }
});
// Deaktivierung
on({ id: '0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_HzgBad' /* SmartPlugBad_HzgBad */, val: false, ack: true }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (SmartPlugBad) {
    setState('fritzdect.0.DECT_116300118701.state' /* Switch Status and Control */, false);
    setState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timeout' /* SmartPlugBad_Timeout */, false);
    setState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Deaktivieren_Intervall' /* SmartPlugBad_Deaktivieren_Intervall */, false);
    HzgBadButtonAktiviert = false;
    HzgBadPVAktiviert = false;
    SmartPlugBad = false;
    if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '--- SmartPlug Bad wurde ausgeschaltet');
    }
  }
});
// HAND
on({ id: 'fritzdect.0.DECT_116300118701.state' /* Switch Status and Control */, val: true, ack: true }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (!HzgBadPVAktiviert) {
    HzgBadButtonAktiviert = true;
    if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'SmartPlug Bad per Hand aktiviert');
    }
  }
});
on({ id: 'fritzdect.0.DECT_116300118701.state' /* Switch Status and Control */, val: false, ack: true }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (HzgBadButtonAktiviert && !HzgBadPVAktiviert) {
    HzgBadButtonAktiviert = false;
    if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'SmartPlug Bad per Hand deaktiviert');
    }
  }
});
// Überwachung ---------------------
schedule("*/5 * * * * *", async () => {
  if (getState('0_userdata.0.AMIS.Grid_Überwachung').val == true) {
    setState('fritzdect.0.DECT_116300118701.state' /* Switch Status and Control */, false, true);
  }
  if (getState('0_userdata.0.AMIS.Power').val > 0) {
    if (getState('fritzdect.0.DECT_116300118701.state').val && !HzgBadButtonAktiviert) {
      setState('fritzdect.0.DECT_116300118701.state' /* Switch Status and Control */, false, true);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Hzg Bad musste abgedreht werden. PV-Überschuss (W): ' + String(('' + getState('0_userdata.0.AMIS.PVÜberschuss').val)));
    }
  }
});
// INIT--------------
createState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_HzgBad', true, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlugBad_HzgBad","role": "","type": "boolean","desc": "Blockly erzeugt","read": true,"write": true,"def": false}'), async () => {
});
createState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timeout', 0, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlugBad_Timeout","role": "","type": "number","desc": "Blockly erzeugt","unit": "s","min": 0,"max": 10000,"def": 0,"read": true,"write": true}'), async () => {
});
createState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Aktiv', 0, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlugBad_Timer_Aktiv","role": "","type": "number","desc": "Blockly erzeugt","unit": "min","min": 0,"max": 10000,"def": 0,"read": true,"write": true}'), async () => {
});
createState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Inaktiv', 0, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlugBad_Timer_Inaktiv","role": "","type": "number","desc": "Blockly erzeugt","unit": "min","min": 0,"max": 10000,"def": 0,"read": true,"write": true}'), async () => {
});
createState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug', false, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlugBad_Debug","role": "","type": "boolean","desc": "Blockly erzeugt","read": true,"write": true,"def": false}'), async () => {
});
createState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Deaktivieren_Intervall', false, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlugBad_Deaktivieren_Intervall","role": "","type": "boolean","desc": "Blockly erzeugt","read": true,"write": true,"def": false}'), async () => {
});
// VIS
createState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Start_VIS', 60, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlugBad_Timer_Start_VIS","role": "","type": "number","desc": "Blockly erzeugt","unit": "min","min": 0,"max": 10000,"def": 0,"read": true,"write": true}'), async () => {
});
createState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Aktiv_VIS', 10, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlugBad_Timer_Aktiv_VIS","role": "","type": "number","desc": "Blockly erzeugt","unit": "min","min": 0,"max": 10000,"def": 0,"read": true,"write": true}'), async () => {
});
createState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Inaktiv_VIS', 10, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlugBad_Timer_Inaktiv_VIS","role": "","type": "number","desc": "Blockly erzeugt","unit": "min","min": 0,"max": 10000,"def": 0,"read": true,"write": true}'), async () => {
});
createState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Grad_VIS', 23, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlugBad_Grad_VIS","role": "","type": "number","desc": "Blockly erzeugt","unit": "°C","min": 20,"max": 30,"def": 0,"read": true,"write": true}'), async () => {
});
HzgBadPVAktiviert = false;
HzgBadButtonAktiviert = false;
SmartPlugBad = false;
Timer = 0;
// RESET
schedule('{"time":{"exactTime":true,"start":"00:01"},"period":{"days":1}}', async () => {
  setState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Aktiv' /* SmartPlugBad_Timer_Aktiv */, 0, true);
  setState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Inaktiv' /* SmartPlugBad_Timer_Inaktiv */, 0, true);
  setState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Deaktivieren_Intervall' /* SmartPlugBad_Deaktivieren_Intervall */, false, true);
});
// LOG
on({ id: [].concat(['0_userdata.0.AMIS.PVÜberschuss']), change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '#######################');
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '- PV-Überschuss (W) : ' + String(('' + getState('0_userdata.0.AMIS.PVÜberschuss').val)));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '- Status SmartPlugBad: ' + String(('' + SmartPlugBad)));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '- Status HzgBadPV: ' + String(('' + HzgBadPVAktiviert)));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '- Status HzgBadHand: ' + String(('' + HzgBadButtonAktiviert)));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '- Status Fritz: ' + String(('' + getState('fritzdect.0.DECT_116300118701.state').val)));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '- VIS Start: ' + String(('' + getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Start_VIS').val)));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '- VIS Aktiv: ' + String(('' + getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Aktiv_VIS').val)));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '- VIS Inaktiv: ' + String(('' + getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Inaktiv_VIS').val)));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '- Timeout: ' + String(('' + getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timeout').val)));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '- Tmp: ' + String(('' + getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Grad_VIS').val)));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '#######################');
  }
});

// Hzg Bad
schedule("* * * * * *", async () => {
  if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx');
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Durchlauf START xxxxxxxxx');
  }
  // Aktiv ?
  if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_HzgBad').val && !getState('0_userdata.0.AMIS.Grid_Überwachung').val) {
    // De-/Aktivieren
    if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx De-/Aktivieren');
    }
    if (!HzgBadButtonAktiviert && getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timeout').val <= 0) {
      if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Durchlauf');
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx PV Überschuss: ' + String(getState('0_userdata.0.AMIS.PVÜberschuss').val));
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Temperatur: ' + String(getState('fritzdect.0.DECT_116300118701.celsius').val));
      }
      if ((getState('0_userdata.0.AMIS.PVÜberschuss').val <= 10 || getState('fritzdect.0.DECT_116300118701.celsius').val > getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Grad_VIS').val) && SmartPlugBad) {
        SmartPlugBad = false;
        HzgBadPVAktiviert = false;
        if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
          await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx ---> SmartPlug Bad deaktiviert');
        }
      } else if (getState('fritzdect.0.DECT_116300118701.celsius').val < getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Grad_VIS').val && getState('0_userdata.0.AMIS.PVÜberschuss').val > 1000 && !SmartPlugBad) {
        SmartPlugBad = true;
        HzgBadPVAktiviert = true;
        if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
          await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx ---> SmartPlug Bad aktiviert');
        }
      }
      // Einschaltzeiten reduzieren
      if (getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Inaktiv').val > 180) {
        setState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Aktiv' /* SmartPlugBad_Timer_Aktiv */, 0);
        setState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Inaktiv' /* SmartPlugBad_Timer_Inaktiv */, 0);
        if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
          await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Timer gelöscht, die Hzg war länger als 180min inaktiv');
        }
      }
      if (HzgBadPVAktiviert) {
        if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
          await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Einschaltzeit kontrollieren, Timer: ' + String(('' + getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Aktiv').val)));
          await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Timer Inaktiv: ' + String(('' + getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Inaktiv').val)));
        }
        if (getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Aktiv').val >= getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Start_VIS').val) {
          if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
            await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Timer_Start: ' + String(('' + getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Start_VIS').val)));
          }
          BerechnungInAktiv = getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Aktiv').val - getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Start_VIS').val;
          if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
            await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Berechnung: ' + String(('' + BerechnungInAktiv)));
          }
          while (getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Aktiv').val >= getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Start_VIS').val && BerechnungInAktiv > 0) {
            if (BerechnungInAktiv > getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Inaktiv_VIS').val) {
              BerechnungInAktiv = BerechnungInAktiv - getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Inaktiv_VIS').val;
              if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
                await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Berechnung Abzug Inaktiv: ' + String(('' + BerechnungInAktiv)));
              }
            } else {
              setState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Deaktivieren_Intervall' /* SmartPlugBad_Deaktivieren_Intervall */, true);
              BerechnungInAktiv = 0;
              if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
                await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Berechnung Inaktivzeitraum gefunden');
              }
              break;
            }
            if (BerechnungInAktiv > getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Aktiv_VIS').val) {
              BerechnungInAktiv = BerechnungInAktiv - getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timer_Aktiv_VIS').val;
              if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
                await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Berechnung Abzug Aktiv: ' + String(('' + BerechnungInAktiv)));
              }
            } else {
              setState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Deaktivieren_Intervall' /* SmartPlugBad_Deaktivieren_Intervall */, false);
              BerechnungInAktiv = 0;
              if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
                await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Berechnung Aktivzeitraum gefunden');
              }
              break;
            }
          }
        }
      }
      // ---------->>>>>> ansteuern
      if (SmartPlugBad && getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Deaktivieren_Intervall').val) {
        if (getState('fritzdect.0.DECT_116300118701.state').val) {
          setState('fritzdect.0.DECT_116300118701.state' /* Switch Status and Control */, false);
          if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
            await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Smart Plug Bad durch Deaktivierung deaktiviert');
          }
        } else {
          await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Smart Plug Bad ist durch Timerintervall deaktiviert');
        }
      } else if (getState('fritzdect.0.DECT_116300118701.state').val != SmartPlugBad) {
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Smart Plug Bad war ungleich');
        setState('fritzdect.0.DECT_116300118701.state' /* Switch Status and Control */, SmartPlugBad);
        if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val == true) {
          if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
            await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Smart Plug Bad geändert: ' + String(('' + SmartPlugBad)));
          }
        }
        if (!SmartPlugBad) {
          setState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timeout' /* SmartPlugBad_Timeout */, 300);
          if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val == true) {
            if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
              await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Smart Plug Bad Timeout: ' + String(('' + getState('0_userdata.0.SmartPlugs_BadHzg.SmartPlugBad_Timeout').val)));
            }
          }
        }
      } else {
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Smart Plug Bad war gleich');
      }
    }
    if (getState('0_userdata.0.SmartPlugs_BadHzg.SmarPlugBad_Debug').val) {
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxx Durchlauf ENDE xxxxxxxxx');
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx');
    }
  }
});


